MultiChannelDrawerReprojectMesh.geometryProgram:
#version 120
#extension GL_EXT_geometry_shader4 : enable

uniform sampler2D col;
uniform sampler2D dep;
uniform vec2 size;
uniform mat4 ReprojectionMatrix;
uniform bool withHoles;
uniform vec2 offset;
uniform vec2 off[] = vec2[4]( vec2(0,0), vec2(0,1), vec2(1,0), vec2(1,1) );
const float tolerance = 10.f;

float depth(vec2 xy) {
   return texture2D(dep, xy/size).r;
}

vec4 pos(vec2 xy, float d) {
   vec4 p = vec4(xy.x/size.x-0.5, 0.5-xy.y/size.y, d-0.5, 0.5)*2.;
   return ReprojectionMatrix * p;
}

vec2 screenpos(vec4 p) {
   return p.xy/p.w*size.xy*0.5+offset;
}

vec2 pos2d(vec2 xy) {
   float d = depth(xy);
   return screenpos(pos(xy, d));
}

bool is_far(float d) {
   return d == 1.;
}

void createVertex(vec2 xy) {
   float d = depth(xy);
   if (is_far(d)) return;

   vec4 color = texture2D(col, xy/size);
   gl_FrontColor = color;
   gl_Position = pos(xy, d);
   EmitVertex();
}

void main() {
   vec2 xy = gl_PositionIn[0].xy;

   bool render = true;
   if (withHoles) {
      vec2 p[4];
      for (int i=0; i<4; ++i)
         p[i] = pos2d(xy+off[i]);
      float mindist = distance(p[0],p[1]), maxdist=mindist;
      for (int i=1; i<4; ++i) {
          for (int j=0; j<i; ++j) {
              float dist = distance(p[i],p[j]);
              mindist = min(mindist, dist);
              maxdist = max(maxdist, dist);
          }
      }
      if (maxdist < 0.001 || mindist*tolerance < maxdist) {
         render = false;
      }
   }
   if (render) {
      for (int i=0; i<4; ++i)
         createVertex(xy+off[i]);
   }
   EndPrimitive();
}
